using System.Windows;using System.Windows.Controls;using MizanDesktop.Models;using MizanDesktop.Services;
namespace MizanDesktop.Views;
public sealed class PartiesView:UserControl{readonly AppRepository repo;readonly DataGrid grid=new(){AutoGenerateColumns=false,IsReadOnly=true,Margin=new Thickness(0,15,0,0)};readonly TextBox search=new(){Width=320,Padding=new Thickness(8)};public PartiesView(AppRepository r){repo=r;FlowDirection=FlowDirection.RightToLeft;var root=new DockPanel();var bar=new StackPanel{Orientation=Orientation.Horizontal};var add=new Button{Content="＋ إضافة عميل/مورد",Padding=new Thickness(14,8,14,8),Margin=new Thickness(8,0,0,0)};add.Click+=(_,_)=>Edit(null);search.TextChanged+=(_,_)=>Load();bar.Children.Add(add);bar.Children.Add(search);DockPanel.SetDock(bar,Dock.Top);root.Children.Add(bar);grid.Columns.Add(new DataGridTextColumn{Header="الاسم",Binding=new System.Windows.Data.Binding("Name")});grid.Columns.Add(new DataGridTextColumn{Header="النوع",Binding=new System.Windows.Data.Binding("Type")});grid.Columns.Add(new DataGridTextColumn{Header="الهاتف",Binding=new System.Windows.Data.Binding("Phone")});grid.Columns.Add(new DataGridTextColumn{Header="الرصيد",Binding=new System.Windows.Data.Binding("Balance"){StringFormat="N2"}});grid.MouseDoubleClick+=(_,_)=>{if(grid.SelectedItem is Party p)Edit(p);};root.Children.Add(grid);Content=root;Load();}void Load(){grid.ItemsSource=repo.Parties.Where(p=>string.IsNullOrWhiteSpace(search.Text)||p.Name.Contains(search.Text,StringComparison.OrdinalIgnoreCase)||p.Phone.Contains(search.Text,StringComparison.OrdinalIgnoreCase)).ToList();}void Edit(Party? party){var p=party??new Party();var w=new Window{Title=party==null?"إضافة طرف":"تعديل طرف",Width=500,Height=430,Owner=Window.GetWindow(this),WindowStartupLocation=WindowStartupLocation.CenterOwner,FlowDirection=FlowDirection.RightToLeft};var s=new StackPanel{Margin=new Thickness(25)};TextBox F(string label,string value){s.Children.Add(new TextBlock{Text=label,Margin=new Thickness(0,8,0,3)});var t=new TextBox{Text=value,Padding=new Thickness(8)};s.Children.Add(t);return t;}var n=F("الاسم",p.Name);var ph=F("الهاتف",p.Phone);var ad=F("العنوان",p.Address);s.Children.Add(new TextBlock{Text="النوع",Margin=new Thickness(0,8,0,3)});var type=new ComboBox{ItemsSource=Enum.GetValues<PartyType>(),SelectedItem=p.Type,Padding=new Thickness(8)};s.Children.Add(type);var b=new Button{Content="حفظ",Padding=new Thickness(15),Margin=new Thickness(0,20,0,0)};b.Click+=(_,_)=>{if(string.IsNullOrWhiteSpace(n.Text)){MessageBox.Show("الاسم مطلوب");return;}p.Name=n.Text;p.Phone=ph.Text;p.Address=ad.Text;p.Type=(PartyType)type.SelectedItem!;repo.SaveParty(p);w.Close();Load();};s.Children.Add(b);w.Content=s;w.ShowDialog();}}
